<script setup>
import {t} from "./i18n.js";
import {ref,onMounted} from 'vue';
const props=defineProps({api:Function});const emit=defineEmits(['changed']);const rows=ref([]),id=ref(null),prioriteit=ref(null),busy=ref(false),error=ref('');
async function load(){rows.value=await props.api('/prioriteiten');}function fresh(){id.value=null;prioriteit.value=null;error.value='';}function choose(r){id.value=r.PrioriteitID;prioriteit.value=r.Prioriteit;error.value='';}
async function change(remove=false){if(busy.value||(!remove&&(!Number.isSafeInteger(prioriteit.value)||prioriteit.value<1)))return;if(remove&&!confirm(t('Prioriteit verwijderen? Bestaande meldingen behouden hun waarde.')))return;busy.value=true;error.value='';try{await props.api('/prioriteiten'+(id.value===null?'':'/'+id.value),{method:remove?'DELETE':id.value===null?'POST':'PATCH',body:remove?undefined:JSON.stringify({Prioriteit:prioriteit.value})});await load();emit('changed');fresh();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=e.message));
</script>
<template><section class="panel"><h2>{{t("Prioriteiten")}}</h2><p v-if="error" class="error">{{t(error)}}</p><form class="field-form" @submit.prevent="change()"><label>{{t("Prioriteit")}}<input type="number" min="1" step="1" v-model.number="prioriteit" required></label><div class="form-actions"><button type="button" class="secondary" @click="fresh" :disabled="busy">{{t("Nieuw")}}</button><button type="button" class="secondary" @click="change(true)" :disabled="busy||id===null">{{t("Verwijderen")}}</button><button :disabled="busy||!Number.isSafeInteger(prioriteit)||prioriteit&lt;1">{{t("Opslaan")}}</button></div></form><table><thead><tr><th>{{t("Prioriteit")}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.PrioriteitID" class="melding-row" :class="{selected:id===r.PrioriteitID}" @click="!busy&&choose(r)" tabindex="0" @keydown.enter="!busy&&choose(r)"><td>{{r.Prioriteit}}</td></tr></tbody></table></section></template>
